INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(29201, 'James 3:15', 'James', 3, 15, '&nbsp;دا هغه حکمت نۀ دے کوم چې د آسمان نه راځى بلکې دُنياوى، نفسانى او شېطانى دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29202, 'James 3:16', 'James', 3, 16, '&nbsp;ځکه چې چرته چې کينه او خود غرضى وى، هلته به فساد او هر قِسم شرارت هم کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29203, 'James 3:17', 'James', 3, 17, '&nbsp;خو چې کوم حِکمت د آسمان نه راځى، اول خو هغه پاک وى، بيا صُلح خوښوونکے، نرم مزاجه، تربيت خوښوونکے، د رحم او د ښو مېوو نه ډک، بې له طرفدارۍ او رياکارۍ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29204, 'James 3:18', 'James', 3, 18, '&nbsp;او صُلح کوونکى د صُلحې سره داسې تخم کَرى چې د صداقت مېوې ترې پېدا کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29205, 'James 4:1', 'James', 4, 1, '&nbsp;ستاسو په مينځ کښې جنګ او جګړې د کومه راغلې؟ ولې دا ستاسو د هغه خواهشاتو په وجه نۀ دى چې په تاسو کښې فساد پېدا کوى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29206, 'James 4:2', 'James', 4, 2, '&nbsp;تاسو چې څۀ غواړئ او حاصلولے يې نۀ نو بيا تاسو قتل کوئ. تاسو د نورو خلقو د څيزونو نه سوزئ، خو تاسو هغه نۀ شئ حاصلولے، نو بيا تاسو د جنګ جګړو نه کار اخلئ. خو تاسو سره هغه څۀ نشته کوم چې تاسو غواړئ ځکه چې تاسو هغه د خُدائ پاک نه نۀ غواړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29207, 'James 4:3', 'James', 4, 3, '&nbsp;تر دې چې تاسو يې غواړئ خو څۀ په لاس نۀ درځى، دا ځکه چې تاسو يې په بد نيت سره غواړئ، د دې دپاره چې تاسو يې په خپل عېش و عشرت ولګوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29208, 'James 4:4', 'James', 4, 4, '&nbsp;اے زناکارو خلقو، ولې تاسو په دې نۀ پوهېږئ چې د دُنيا سره ملګرتيا کول د خُدائ پاک سره دشمنى کول دى؟ نو ځکه څوک چې د دې شريرې دُنيا سره مينه کوى، هغه د خُدائ پاک سره دشمنى کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29209, 'James 4:5', 'James', 4, 5, '&nbsp;يا تاسو دا ګڼئ چې مقدس کِتاب بې‌فائدې وائى چې، ”خُدائ پاک چې کوم روح زمونږ په زړُونو کښې اچولے دے، هغه د حسد خواهش ساتى څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29210, 'James 4:6', 'James', 4, 6, '&nbsp;بلکې هغه په مونږ زيات فضل کوى، نو ځکه صحيفې دا فرمائى چې، ”خُدائ پاک د کبرژنو مقابله کوى خو عاجزانو له فضل ورکوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29211, 'James 4:7', 'James', 4, 7, '&nbsp;نو په دې وجه خپل ځانونه بيا د خُدائ پاک تابع کړئ، او د اِبليس مقابله وکړئ نو هغه به تاسو نه وتښتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29212, 'James 4:8', 'James', 4, 8, '&nbsp;تاسو خُدائ پاک ته رانزدې شئ او هغه به تاسو ته رانزدې شى. اے ګناهګارانو، خپل لاسونه د بدو کارونو نه صفا کړئ او اے دوه زړيو خلقو، خپل زړونه پاک کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29213, 'James 4:9', 'James', 4, 9, '&nbsp;په خپلو اعمالو وير او ژړا وکړئ، ستاسو خندا دې په وير بدله شى او ستاسو خوشحالى دې په غم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29214, 'James 4:10', 'James', 4, 10, '&nbsp;خپل ځان د مالِک په وړاندې عاجز کړئ او هغه به تاسو له عزت درکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29215, 'James 4:11', 'James', 4, 11, '&nbsp;اے وروڼو او خوېندو، د يو بل خلاف خبرې مۀ کوئ. څوک چې د خپل ورور خلاف خبرې کوى يا په بل چا اِلزام لګوى، هغه د شريعت بد وائى او په شريعت اِلزام لګوى، خو کۀ تۀ په شريعت اِلزام لګوې نو تۀ په شريعت عمل کوونکے نه، بلکې په هغې قاضى يې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29216, 'James 4:12', 'James', 4, 12, '&nbsp;خو د شريعت ورکوونکے او قاضى خو يو دے چې د بچ کولو او د هلاکولو قدرت ورسره شته، نو بيا تۀ څوک يې چې په خپل ګاونډى اِلزام لګوې؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29217, 'James 4:13', 'James', 4, 13, '&nbsp;په تاسو کښې څوک چې دا وائى چې، ”مونږ به نن يا سبا فلانکى ښار ته لاړ شُو او هلته به يو کال تېر کړُو او په تجارت کښې به ګټه وکړُو،“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29218, 'James 4:14', 'James', 4, 14, '&nbsp;خو اوس تاسو په دې نۀ يئ خبر چې سبا به څۀ کيږى، ستاسو ژوند څۀ څيز دے؟ د يو دوند په شان دے چې د لږ ساعت دپاره ښکاره شى او بيا فنا شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29219, 'James 4:15', 'James', 4, 15, '&nbsp;د دې په ځائ تاسو له دا وئيل په کار دى چې، ”کۀ د مالِک خُدائ رضا وى نو مونږ به ژوندى پاتې شُو او دا يا هغه کار به وکړُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29220, 'James 4:16', 'James', 4, 16, '&nbsp;خو تاسو په خپلو ډوزو فخر کوئ خو دا قِسم فخر کول بد دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29221, 'James 4:17', 'James', 4, 17, '&nbsp;نو بيا کۀ څوک په ښۀ کولو پوهيږى او نۀ يې کوى، نو هغه ګناه کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29222, 'James 5:1', 'James', 5, 1, '&nbsp;اے مالدارو واورئ، تاسو په خپلو هغه مصيبتونو چې راتلونکى دى، ژړا او فرياد وکړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29223, 'James 5:2', 'James', 5, 2, '&nbsp;ستاسو مال دولت سخا شو او ستاسو جامې چينجو ووهلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29224, 'James 5:3', 'James', 5, 3, '&nbsp;ستاسو سرۀ زر او سپين زر زنګ شول او د دې زنګ به ستاسو خلاف ګواهى ورکوى، او دا به ستاسو غوښې لکه د اور په شان وسوزوى. تاسو په دې آخرى ورځو کښې خزانې رايوځائ کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29225, 'James 5:4', 'James', 5, 4, '&nbsp;ګورئ، کومو مزدورانو چې ستاسو په پټو کښې لَو کړے دے، د هغوئ هغه مزدورى چې تاسو په دوکه ايساره کړې ده، چغې وهى او د لَوګرو فرياد ربُ الافواج خُدائ غوږُونو ته رسېدلے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29226, 'James 5:5', 'James', 5, 5, '&nbsp;تاسو په دُنيا کښې د عېش او عشرت ژوند تېر کړو، او تاسو خپل ځانونه د حلالېدو د ورځ دپاره څورب کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29227, 'James 5:6', 'James', 5, 6, '&nbsp;تاسو صادق سړے قصوروار کړو او ومو وژلو، خو هغۀ ستاسو مقابله نۀ کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29228, 'James 5:7', 'James', 5, 7, '&nbsp;نو اے وروڼو او خوېندو، د مالِک تر راتلو پورې صبر وکړئ، لکه څنګه چې يو زميندار د زمکې د قيمتى فصل په اِنتظار کښې د منى او د سپرلى د باران تر ورېدو پورې صبر کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29229, 'James 5:8', 'James', 5, 8, '&nbsp;نو تاسو هم صبر وکړئ او خپل زړونه مضبوط کړئ ځکه چې د مالِک راتلل رانزدې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29230, 'James 5:9', 'James', 5, 9, '&nbsp;اے وروڼو او خوېندو، د يو بل خلاف شکايت مۀ کوئ نو چې تاسو سزا ونۀ مومئ. ګورئ، قاضى په دروازه کښې ولاړ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29231, 'James 5:10', 'James', 5, 10, '&nbsp;اے وروڼو او خوېندو، کومو نبيانو چې د مالِک په نوم کلام وکړو، د هغوئ تکليفونه تېرول او صبر کول خپل ځانته نمونه وګڼئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29232, 'James 5:11', 'James', 5, 11, '&nbsp;واقعى چې مونږ هغوئ ته بختور وايو څوک چې صبر کوونکى دى. تاسو د ايُوب د صبر په حقله اورېدلى دى او تاسو د مالِک مقصد هم وليدو چې مالِک څومره ډېر مهربانه او رحيم دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29233, 'James 5:12', 'James', 5, 12, '&nbsp;خو اے زما وروڼو او خوېندو، د ټولو نه لويه خبره دا ده چې قسم ونۀ خورئ، نۀ د آسمان او نۀ د زمکې او نۀ د څۀ بل څيز، بلکې ستاسو ”آو“ دې ”آو“ وى او ستاسو ”نه“ دې ”نه“ وى، نو چې تاسو د سزا لائق ونۀ ګرځئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29234, 'James 5:13', 'James', 5, 13, '&nbsp;کۀ په تاسو کښې څوک په تکليف کښې وى نو دُعا دې وغواړى، کۀ خوشحاله وى نو هغوئ دې ثنا ووائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29235, 'James 5:14', 'James', 5, 14, '&nbsp;کۀ په تاسو کښې څوک بيمار وى نو هغوئ دې د جماعت مشران راوبلى او د هغۀ دپاره دې هغوئ دُعا وغواړى او د مالِک په نوم دې هغوئ په تېلو مسح کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29236, 'James 5:15', 'James', 5, 15, '&nbsp;او کومه دُعا چې په ايمان سره وغوښتے شى د هغې په وجه به بيمار روغ شى، او مالِک به هغه راپاڅوى او کۀ هغۀ ګناهونه کړى وى نو هغه به ورته معاف شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29237, 'James 5:16', 'James', 5, 16, '&nbsp;نو بيا ځکه تاسو په خپلو کښې يو بل ته د خپلو ګناهونو اِقرار وکړئ او د يو بل دپاره دُعا وغواړئ نو چې تاسو شفا ومومئ. د زړۀ نه د صادقه دُعا ډېر اثرناکه وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29238, 'James 5:17', 'James', 5, 17, '&nbsp;الياس زمونږ په شان انسان وو، او هغۀ ډېر په جوش سره دُعا وغوښته چې باران دې ونۀ وريږى، او تر درې نيمو کالو پورې په زمکه باران ونۀ ورېدلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29239, 'James 5:18', 'James', 5, 18, '&nbsp;نو چې هغۀ بيا دُعا وغوښتله نو د آسمان نه باران وورېدو او په زمکه فصل زرغون شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29240, 'James 5:19', 'James', 5, 19, '&nbsp;اے زما وروڼو او خوېندو، کۀ څوک په تاسو کښې د حق د لارې نه واوړى او بل څوک هغه بيا واپس راواړوى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29241, 'James 5:20', 'James', 5, 20, '&nbsp;نو تاسو په دې پوهه شئ چې څوک چې ګناه ګار د ګمراهۍ نه راواړوى، هغه به يو کس د مرګ نه بچ کړى او په ډېرو ګناهونو به پړده واچوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29242, '1 Peter 1:1', '1 Peter', 1, 1, '&nbsp;د پطروس د طرف نه چې د عيسىٰ مسيح رسول دے، د خُدائ پاک د هغه غوره شوو مهاجرينو په نوم چې د پونطوس، ګلتيه، کپدوکيه، آسيه او بتونيه په صوبو کښې خوارۀ وارۀ دى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29243, '1 Peter 1:2', '1 Peter', 1, 2, '&nbsp;تاسو چې خُدائ پلار د ازل نه د خپل عِلم په مطابق د روحُ القُدس په وسيله مقدس کړئ او د عيسىٰ مسيح د وينى تويولو په وسيله يې تاسو د هغۀ تابعدار کړئ، په تاسو دې ډېر فضل او سلامتى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29244, '1 Peter 1:3', '1 Peter', 1, 3, '&nbsp;زمونږ د مالِک عيسىٰ مسيح د خُدائ پاک او پلار دې ثنا وى، چې په خپل لوئ رحمت يې د عيسىٰ مسيح د مړو نه د بيا ژوندى کېدو په وسيله مونږ له د ژوندى اُميد دپاره نوے ژوند راکړو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29245, '1 Peter 1:4', '1 Peter', 1, 4, '&nbsp;او چې يو نۀ فنا کېدونکے، بې‌داغه او لازواله ميراث حاصل کړُو، چې ستاسو دپاره په آسمان کښې ساتلے شوے دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29246, '1 Peter 1:5', '1 Peter', 1, 5, '&nbsp;کوم چې خُدائ پاک د ايمان په وسيله په خپل قُدرت سره محفوظ ساتى يعنې هغه خلاصون چې هغه په آخرى وخت کښې ښکاره کېدو ته تيار دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29247, '1 Peter 1:6', '1 Peter', 1, 6, '&nbsp;نو په دې وجه تاسو خوشحالى وکړئ، اګر چې اوس تاسو د لږ وخت دپاره مختلف تکليفونه وزغمل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29248, '1 Peter 1:7', '1 Peter', 1, 7, '&nbsp;او دا آزمېښتونه به دا خبره ثابته کړى چې ستاسو ايمان اصلى دے، او دا وآزمائيلے شو لکه څنګه چې سرۀ زر په اور آزمائيلے کيږى، خو ستاسو ايمان د فانى سرو زرو نه ډېر زيات قيمتى دے. نو ستاسو ايمان به د عيسىٰ مسيح د راښکاره کېدو په ورځ د جلال او احترام سبب شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29249, '1 Peter 1:8', '1 Peter', 1, 8, '&nbsp;تاسو هغۀ سره داسې مينه کوئ اګر چې هغه مو ليدلے نۀ دے. او نۀ يې اوس وينئ، خو تاسو په هغۀ يقين ساتئ، او په جلالى انداز کښې خوشحالى کوئ کومه چې د بيان نه بهر ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29250, '1 Peter 1:9', '1 Peter', 1, 9, '&nbsp;او ستاسو د ايمان اجر به ستاسو د خپل ځان د خلاصون حاصلول وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29251, '1 Peter 1:10', '1 Peter', 1, 10, '&nbsp;د دې خلاصون په حقله نبيانو ډېر لټون او تحقيق وکړو او د هغه فضل په حقله يې پېشګوئى وکړه کوم چې په تاسو کېدونکے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29252, '1 Peter 1:11', '1 Peter', 1, 11, '&nbsp;د مسيح روح په هغوئ کښې وو او دا ګواهى يې ورکوله چې مسيح به تکليفونه وزغمى او بيا به جلال ومومى، نو بيا نبيانو دا کوشش وکړو چې د روح دا اِشاره به په څۀ وخت او په کوم حالت کښې پوره کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29253, '1 Peter 1:12', '1 Peter', 1, 12, '&nbsp;هغوئ ته وئيلے شوى وُو چې د هغوئ زيرے د هغوئ د خپل ځان دپاره نۀ وو بلکې ستاسو دپاره وو. نو اوس دا زيرے تاسو ته د هغه چا په وسيله چې د روحُ القُدس په طاقت سره چې د آسمان نه نازل شوے دے بيان شو. دا داسې عجيبه خبرې دى چې فرښتې هم په ليوالتيا سره د دې د کېدو خواهش کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29254, '1 Peter 1:13', '1 Peter', 1, 13, '&nbsp;نو په دې وجه خپله په ذهنى توګه ملا وتړه، او په خپل ځان قابو وساته، او خپل مکمل اُميد په هغه فضل ساتئ کوم به چې عيسىٰ مسيح تاسو له درکړى کله چې هغه راڅرګند شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29255, '1 Peter 1:14', '1 Peter', 1, 14, '&nbsp;تاسو لکه د تابعدارو بچو په شان شئ، او د خپل جهالت د زمانې غوندې د زړو خواهشاتو غلامان مۀ جوړېږئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29256, '1 Peter 1:15', '1 Peter', 1, 15, '&nbsp;څنګه چې ستاسو رابلونکے پاک دے نو هغه شان تاسو په خپل ټول چال چلن کښې خپل ځان پاک کړئ', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29257, '1 Peter 1:16', '1 Peter', 1, 16, '&nbsp;لکه چې صحيفې فرمائى چې، ”پاک شئ ځکه چې زۀ پاک يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29258, '1 Peter 1:17', '1 Peter', 1, 17, '&nbsp;او دا خبره ياد ساتئ هغه آسمانى پلار چا نه چې تاسو دُعا غواړئ هغه د چا طرفدارى نۀ کوى. بلکې هغه به ستاسو اِنصاف کوى او ستاسو د عمل په مطابق به تاسو له اجر درکړى، نو بيا په دُنيا کښې خپل ژوند د هغۀ نه په يرې او لکه د مسافرو په شان تېروئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29259, '1 Peter 1:18', '1 Peter', 1, 18, '&nbsp;نو تاسو په دې پوهه يئ چې خُدائ پاک ستاسو په ځائ فديه ورکړه چې تاسو له د هغه بې‌فائدې ژوندون خلاصون درکړى کوم چې تاسو ته ستاسو د پلار نيکونو نه په ميراث کښې پاتې شوے وو. او کومه فديه چې هغۀ ورکړه نو هغه فانى سرۀ يا سپين زر نۀ وُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29260, '1 Peter 1:19', '1 Peter', 1, 19, '&nbsp;بلکې د مسيح قيمتى وينه وه. هم هغه لکه د روغ رمټ او بې‌داغه ګډُورى په شان قربان شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29261, '1 Peter 1:20', '1 Peter', 1, 20, '&nbsp;هغه د دُنيا د پېدايښت نه اول غوره شوے وو، خو په آخره زمانه کښې ستاسو دپاره ښکاره شو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29262, '1 Peter 1:21', '1 Peter', 1, 21, '&nbsp;د هغۀ په وسيله تاسو په هغه خُدائ ايمان راوړو چا چې هغه د مړو نه بيا راژوندے کړو او جلال يې ورکړو د دې دپاره چې ستاسو ايمان او اُميد په خُدائ پاک وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29263, '1 Peter 1:22', '1 Peter', 1, 22, '&nbsp;تاسو د خپلو ګناهونو نه هغه وخت پاک شوئ کله چې تاسو د حق تابعدارى وکړه، نو اوس تاسو د يو بل سره د زړۀ نه لکه د وروڼو او خوېندو په شان مينه کوئ، په خپلو کښې د يو بل سره د زړۀ د کومې نه مينه ساتئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29264, '1 Peter 1:23', '1 Peter', 1, 23, '&nbsp;ځکه چې ستاسو دوباره پېدا کېدل د فانى کېدونکى تخم نه نه بلکې د نۀ فانى کېدونکى تخم نه د خُدائ پاک د ژوندى او قائم کلام په وسيله بيا پېدا شوئ يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29265, '1 Peter 1:24', '1 Peter', 1, 24, '&nbsp;ځکه چې، ”هر انسان د واښو په شان دے او د دوئ ټول شان او شوکت د ځنګلى ګل په شان دے، واښۀ اوچيږى او ګل رژيږى', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29266, '1 Peter 1:25', '1 Peter', 1, 25, '&nbsp;خو د مالِک خُدائ کلام د همېشه دپاره قائم وى.“ او دا کلام هغه زيرے دے کوم چې تاسو ته بيان شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29267, '1 Peter 2:1', '1 Peter', 2, 1, '&nbsp;نو ځکه بيا هر قِسم بدى، فريب، رياکارى، کينه او هر قِسم بده وينا پرېږدئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29268, '1 Peter 2:2', '1 Peter', 2, 2, '&nbsp;لکه د نوؤ پېدا شوو ماشومانو په شان د خالص روحانى پيو خواهشمند اوسئ نو چې د دې په وسيله تاسو په خلاصون کښې لوئ شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29269, '1 Peter 2:3', '1 Peter', 2, 3, '&nbsp;اوس تاسو د مالِک د مهربانه کېدو خوند اخستے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29270, '1 Peter 2:4', '1 Peter', 2, 4, '&nbsp;نو مسيح ته راشئ چې ژوندے کاڼے دے اګر کۀ بنى آدمو هغه رد کړے دے خو هغه غوره کړے شوے او د خُدائ پاک په نظر کښې قيمتى دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29271, '1 Peter 2:5', '1 Peter', 2, 5, '&nbsp;تاسو هم د ژوندو کاڼو په شان يئ چې خُدائ پاک ترې نه خپل روحانى کور جوړوى چې د اِمامانو مقدسه فرقه په جوړېدو داسې روحانى قربانۍ پېش کړئ چې د عيسىٰ مسيح په وسيله خُدائ پاک ته قبولې وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29272, '1 Peter 2:6', '1 Peter', 2, 6, '&nbsp;ځکه چې صحيفې فرمائى چې، ”ګورئ، زۀ په صيون کښې د ګوټ غوره کړے او قيمتى کاڼے ږدم، او څوک چې په هغۀ ايمان راوړى هغه به شرمنده نۀ شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29273, '1 Peter 2:7', '1 Peter', 2, 7, '&nbsp;نو بيا ستاسو دپاره چې ايمان مو راوړے دے، هغه قيمتى دے خو چا چې ايمان نۀ دے راوړے د هغوئ دپاره، ”کوم کاڼے چې ګِلکارانو رد کړو هغه د ګوټ سر کاڼے شو،“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29274, '1 Peter 2:8', '1 Peter', 2, 8, '&nbsp;او، ”يو داسې کاڼے چې د تيندک باعث جوړيږى او خلق پرې تيندک خورى او راغورزيږى.“ هغوئ تيندک خورى ځکه چې هغوئ د کلام نافرمانى کوى او هغوئ د دې کولو دپاره اول نه مقرر شوى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29275, '1 Peter 2:9', '1 Peter', 2, 9, '&nbsp;خو تاسو يو غوره کړے شوے نسل، د شاهى اِمامانو فرقه، مقدس قوم، او د خُدائ پاک خپل اُمت يئ، د دې دپاره چې تاسو د هغۀ لوئ کارونه بيان کړئ چا چې تاسو د تيارې نه خپلې عجيبه رڼا ته رابللى يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29276, '1 Peter 2:10', '1 Peter', 2, 10, '&nbsp;مخکښې تاسو د خُدائ پاک اُمت نۀ وئ خو اوس يئ، مخکښې په تاسو رحمت نۀ وو شوے خو اوس په تاسو رحمت وشو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29277, '1 Peter 2:11', '1 Peter', 2, 11, '&nbsp;خوږو ملګرو، زۀ تاسو له خبردارے درکوم چې تاسو خپل ځانونه مسافر او مهاجر وګڼئ، د هغه جسمانى خواهشونو نه ځان ساتئ چې ستاسو د نفس سره جنګ کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29278, '1 Peter 2:12', '1 Peter', 2, 12, '&nbsp;په غېر‌يهوديانو کښې خپل چال چلن نېک ساتئ، تر دې چې کله هغوئ ستاسو خلاف لکه د بدکارو په شان بدرد هم وائى، خو هغوئ ستاسو نېک کارونه ووينى او د عدالت په ورځ د خُدائ پاک ثناء ووائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29279, '1 Peter 2:13', '1 Peter', 2, 13, '&nbsp;د مالِک دپاره د بنى آدم د هر يو اِنتظام تابع اوسئ، لکه د بادشاه چې هغه د ټولو نه لوئ دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29280, '1 Peter 2:14', '1 Peter', 2, 14, '&nbsp;او يا د حاکمانو چې هغه د بدکارانو د سزا او د نېکانو د تعريف دپاره هغۀ مقرر کړى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29281, '1 Peter 2:15', '1 Peter', 2, 15, '&nbsp;ځکه چې دا د خُدائ پاک رضا ده چې تاسو نېکى کوئ او په دې کولو سره د ناپوهه خلقو د جهالت خبرې خاموشه کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29282, '1 Peter 2:16', '1 Peter', 2, 16, '&nbsp;تاسو آزاد يئ او آزاد ژوند تېروئ، خپله آزادى د بدۍ کولو پړده مۀ جوړَوئ بلکې د خُدائ پاک د غلامانو په شان ژوند تېروئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29283, '1 Peter 2:17', '1 Peter', 2, 17, '&nbsp;د هر چا عزت کوئ، د ايماندارانو د خاندان سره مينه کوئ، د خُدائ پاک نه يرېږئ او د بادشاه عزت کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
