(29289, '1 Peter 2:23', '1 Peter', 2, 23, '&nbsp;نۀ هغۀ د کنځلو په بدل کښې کنځل کول او نۀ يې په مصيبتونو زغملو چا ته دهمکى ورکوله بلکې هغۀ خپل ځان رښتونى اِنصاف کوونکى ته وسپارلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29290, '1 Peter 2:24', '1 Peter', 2, 24, '&nbsp;هغۀ په خپله زمونږ ګناهونه سولۍ ته د خپل ځان سره يوړل د دې دپاره چې مونږ ګناهونو نه آزاد شُو او د صداقت دپاره ژوند تېر کړُو. او د هغۀ په زخمونو تاسو شفا وموندله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29291, '1 Peter 2:25', '1 Peter', 2, 25, '&nbsp;ځکه چې تاسو د بې‌لارې ګډو په شان ګرځېدئ خو اوس تاسو خپل شپونکى او حفاظت کوونکى له بيا راغلى يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29292, '1 Peter 3:1', '1 Peter', 3, 1, '&nbsp;اے ښځو، هم دغه شان تاسو هم د خپلو خاوندانو تابعدارې اوسئ، نو کۀ چرې په هغوئ کښې ځينې د خُدائ پاک کلام نۀ منى نو چې بيا هم هغوئ ستاسو چال چلن ته وګورى نو ستاسو د خبرو نه بغېر به خُدائ پاک ته راواوړى', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29293, '1 Peter 3:2', '1 Peter', 3, 2, '&nbsp;کله چې هغوئ وګورى چې تاسو څومره په پاکوالى سره د خُدائ پاک په يره کښې ژوند تېروئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29294, '1 Peter 3:3', '1 Peter', 3, 3, '&nbsp;ستاسو ډول او سنګار دې ظاهرى نۀ وى، يعنې سر کمڅۍ کول او د سرو زرو کالى او قِسما قِسم جامې اغوستل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29295, '1 Peter 3:4', '1 Peter', 3, 4, '&nbsp;بلکې ستاسو غېر فانى ډول سنګار دې په هغه باطنى انسانيت کښې په حليمۍ او په سکون کښې وى چې د خُدائ پاک په نزد ډېر قيمتى دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29296, '1 Peter 3:5', '1 Peter', 3, 5, '&nbsp;او په پخوا زمانه کښې هم په خُدائ پاک اُميد ساتونکو پاکو ښځو به خپل ځانونه داسې سنګارول چې د خپلو خاوندانو تابعدارې وې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29297, '1 Peter 3:6', '1 Peter', 3, 6, '&nbsp;لکه څنګه چې ساره د اِبراهيم تابعداره وه او هغۀ ته يې خپل مالِک وئيل. نو تاسو به هم د هغې لوڼه يئ، خو کۀ چرې تاسو نېک کارونه کوئ او د يو څيز نه هم مۀ يرېږئ کوم چې خلق يروى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29298, '1 Peter 3:7', '1 Peter', 3, 7, '&nbsp;اے خاوندانو، هم دغه شان تاسو هم د خپلو ښځو سره په احترام سره ژوند کوئ او د ښځو لکه د نازکو لوښو په شان عزت کوئ ځکه چې هغوئ تاسو سره د ژوند په نعمت کښې وارثانې دى، نو هسې نه چې ستاسو دُعاګانې د قبلېدو نه ايسارې شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29299, '1 Peter 3:8', '1 Peter', 3, 8, '&nbsp;غرض دا چې تاسو ټول په يو زړۀ او په همدردۍ اوسېږئ، د ورورولۍ مينه کوئ، نرم زړۀ او حليمان اوسئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29300, '1 Peter 3:9', '1 Peter', 3, 9, '&nbsp;د بدو په بدل کښې چا سره بد مۀ کوئ او د کنځلو په بدل کښې چا ته کنځل مۀ کوئ، بلکې د دې په ځائ ورله برکت وغواړئ ځکه چې تاسو د دې دپاره رابللے شوى يئ چې د برکت وارثان شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');